function unused_sequences(string $nodeId,int $count,string $siteId='pup'): array {$pdo=db();$q=$pdo->prepare('SELECT id FROM hiker_nodes WHERE node_id=?');$q->execute([$nodeId]);$hiker=(int)$q->fetchColumn();if(!$hiker)throw new RuntimeException("missing seeded hiker $nodeId");$q=$pdo->prepare('SELECT sequence_number FROM uplink_packets WHERE site_id=? AND hiker_node_id=?');$q->execute([$siteId,$hiker]);$used=array_fill_keys(array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN)),true);$free=[];for($i=65535;$i>=0&&count($free)<$count;$i--)if(!isset($used[$i]))$free[]=$i;if(count($free)<$count)throw new RuntimeException('No unused test sequence numbers remain.');return $free;}
